class Solution:
    def numSteps(self, s: str) -> int:
        size = len(s)
        if size == 1:
            return 0
        one_group = s.split('0')
        zero_group = s.split('1')


        if size - len(zero_group[-1]) == 1:
            return size - 1
        else:
            return size + len(one_group) - len(zero_group[-1])

class Solution:
    def numSteps(self, s: str) -> int:
        result, carry = 0, 0
        for i in reversed(range(1, len(s))):
            if int(s[i]) + carry == 1:
                carry = 1  # once it was set, it would keep carrying forever
                result += 2
            else:
                result += 1
        return result+carry

