class Solution:
    def entityParser(self, text: str) -> str:
        patterns = ["&quot;", "&apos;", "&amp;", "&gt;", "&lt;", "&frasl;"]
        chars = ["\"", "'", "&", ">", "<", "/"]
        trie = AhoTrie(patterns)
        positions = []
        for i in range(len(text)):
            for j in trie.step(text[i]):
                positions.append([i-len(patterns[j])+1, j])
        result = []
        i, j = 0, 0
        while i != len(text):
            if j == len(positions) or i != positions[j][0]:                    
                result.append(text[i])
                i += 1
            else:
                result.append(chars[positions[j][1]])
                i += len(patterns[positions[j][1]])
                j += 1
        return "".join(result)

class Solution:
    def numOfWays(self, n: int) -> int:
        two_c_options = 6
        tot_options = 12
        for i in range(n-1):
            temp = tot_options
            tot_options = (two_c_options * 5) + ((tot_options - two_c_options) * 4)
            two_c_options = (two_c_options * 3) + ((temp - two_c_options) * 2)
            tot_options = tot_options % (1000000007)
        return tot_options
